import { useContext, useState } from "react";
import { AuthContext } from "../context/AuthContext";
import API from "../api";
import { useNavigate } from "react-router-dom";

function RegisterButton({ event, isRegistered, refresh }) {
  const { user } = useContext(AuthContext);
  const navigate = useNavigate();
  const [loading, setLoading] = useState(false);

  const handleRegister = async () => {
    try {
      setLoading(true);
      await API.post(`/events/${event._id}/register`, {}, {
        headers: {
          Authorization: `Bearer ${localStorage.getItem("token")}`,
        },
      });
      refresh();
    } catch (err) {
      alert(err.response?.data?.msg || "Error");
    } finally {
      setLoading(false);
    }
  };

  if (!user) {
    return <button onClick={() => navigate("/login")}>Login to Register</button>;
  }

  if (isRegistered) {
    return <button disabled>Already Registered</button>;
  }

  if (event.availableSeats <= 0) {
    return <p style={{ color: "red" }}>Sold Out</p>;
  }

  return (
    <button onClick={handleRegister}>
      {loading ? "Registering..." : "Register Now"}
    </button>
  );
}

export default RegisterButton;
